def minimumDistance(points):
    def manhattan_distance(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def max_distance_without_point(points, exclude_idx):
        max_dist = 0
        for i in range(len(points)):
            if i == exclude_idx:
                continue
            for j in range(i + 1, len(points)):
                if j == exclude_idx:
                    continue
                dist = manhattan_distance(points[i], points[j])
                max_dist = max(max_dist, dist)
        return max_dist

    min_max_distance = float('inf')

    for i in range(len(points)):
        # Remove point i and find maximum distance among remaining points
        max_dist = max_distance_without_point(points, i)
        min_max_distance = min(min_max_distance, max_dist)

    return min_max_distance
