def shortestSubstrings(arr):
    n = len(arr)
    answer = [""] * n

    for i in range(n):
        # Get all substrings of arr[i] sorted by length and then lexicographically
        substrings = []
        for length in range(1, len(arr[i]) + 1):
            for start in range(len(arr[i]) - length + 1):
                substrings.append(arr[i][start:start + length])

        # Sort by length first, then lexicographically
        substrings.sort(key=lambda x: (len(x), x))

        # Check each substring to see if it appears in any other string
        for substr in substrings:
            found_in_other = False
            for j in range(n):
                if i != j and substr in arr[j]:
                    found_in_other = True
                    break

            if not found_in_other:
                answer[i] = substr
                break

    return answer
