        return bin(n).count('1')

    # Group elements by their set bit count
    groups = []
    current_group = []
    current_bit_count = count_set_bits(nums[0])

    for num in nums:
        bit_count = count_set_bits(num)
        if bit_count == current_bit_count:
            current_group.append(num)
        else:
            if current_group:
                groups.append(current_group)
            current_group = [num]
            current_bit_count = bit_count

    # Don't forget the last group
    if current_group:
        groups.append(current_group)

    # For each group, check if its elements can be arranged to match sorted order
    sorted_nums = sorted(nums)
    sorted_groups = []
    current_sorted_group = []
    current_bit_count = count_set_bits(sorted_nums[0])

    for num in sorted_nums:
        bit_count = count_set_bits(num)
        if bit_count == current_bit_count:
            current_sorted_group.append(num)
        else:
            if current_sorted_group:
                sorted_groups.append(current_sorted_group)
            current_sorted_group = [num]
            current_bit_count = bit_count

    # Don't forget the last group
    if current_sorted_group:
        sorted_groups.append(current_sorted_group)

    # Check if the group structures are compatible
    if len(groups) != len(sorted_groups):
        return False

    # Check if each group contains the same elements as the corresponding sorted group
    for i in range(len(groups)):
