        while b:
            a, b = b, a % b
        return a

    def find_parent(parent, x):
        if parent[x] != x:
            parent[x] = find_parent(parent, parent[x])
        return parent[x]

    def union(parent, rank, x, y):
        px, py = find_parent(parent, x), find_parent(parent, y)
        if px == py:
            return
        if rank[px] < rank[py]:
            px, py = py, px
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1

    # Create union-find structure
    parent = list(range(len(nums)))
    rank = [0] * len(nums)

    # Group indices by prime factors
    prime_to_indices = {}

    for i, num in enumerate(nums):
        temp = num
        d = 2
        while d * d <= temp:
            if temp % d == 0:
                while temp % d == 0:
                    temp //= d
                if d not in prime_to_indices:
                    prime_to_indices[d] = []
                prime_to_indices[d].append(i)
            d += 1
        if temp > 1:
            if temp not in prime_to_indices:
