        for reel in S:
            reel_times = []
            for t in range(M * 3):  # We need to consider at most 3 full cycles (worst case)
                if reel[t % M] == digit:
                    reel_times.append(t)
            if not reel_times:
                valid = False
                break
            times.append(reel_times)

        if not valid:
            continue

        # Try all combinations of times from each reel
        # We want the minimum maximum time across all combinations
        for t1 in times[0]:
            for t2 in times[1]:
                if t2 == t1:
                    continue  # Can't press two buttons at the same time
                for t3 in times[2]:
                    if t3 == t1 or t3 == t2:
                        continue  # Can't press two buttons at the same time
                    # The total time is the maximum of the three stopping times
                    max_time = max(t1, t2, t3)
                    min_time = min(min_time, max_time)

