def number_of_ways(n: int, x: int) -> int:
    MOD = 10**9 + 7
    max_base = int(n ** (1.0 / x)) + 1
    powers = []
    for i in range(1, max_base + 1):
        p = i ** x
        if p <= n:
            powers.append(p)
        else:
            break

    dp = [0] * (n + 1)
    dp[0] = 1

    for p in powers:
        for s in range(n, p - 1, -1):
            dp[s] = (dp[s] + dp[s - p]) % MOD

    return dp[n]
