                selected_tiles.append(tiles[i])
                total_selected_area += get_areas(tiles[i])

        # Only proceed if the area matches
        if total_selected_area != total_area:
            continue

        # Try to pack the selected tiles into the H x W grid
        # Use backtracking with grid representation
        grid = [[False] * W for _ in range(H)]

